const body = $input.first().json.body ?? {};
const required = ['name','email','company','need','budget','timeline'];
for (const key of required) { if (typeof body[key] !== 'string' || !body[key].trim()) throw new Error('Missing required field: ' + key); }
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) throw new Error('Invalid email format');
const budget = { high: 25, mid: 18, low: 8, unknown: 0 }[body.budget];
const timing = { soon: 30, later: 18, research: 5 }[body.timeline];
if (budget === undefined || timing === undefined) throw new Error('Unsupported budget or timeline value');
const decision = body.decision_maker === true || body.decision_maker === 'true';
const needPoints = /autom(at|ation)|workflow|agent|support|crm|process/i.test(body.need) ? 35 : 10;
const score = needPoints + budget + timing + (decision ? 10 : 0);
const qualified = score >= 70;
return [{json:{lead_id:'demo-' + Date.now(),name:body.name.trim(),email:body.email.trim().toLowerCase(),company:body.company.trim(),need:body.need.trim(),score,score_reasons:{need:needPoints,budget,timeline:timing,decision_maker:decision?10:0},qualification_status:qualified?'qualified':'needs_review',approval_status:qualified?'pending':'not_required',crm_action:'none_demo_only',outreach_sent:false,demo_mode:true}}];
